import{_ as t,c as n,o,ae as r}from"./chunks/framework.CQ8DW7XN.js";const u=JSON.parse('{"title":"netapp-openshift-console-[trident,protect]","description":"","frontmatter":{},"headers":[],"relativePath":"docs/noc/noc.md","filePath":"docs/noc/noc.md"}'),a={name:"docs/noc/noc.md"};function p(i,e,s,c,l,d){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="netapp-openshift-console-trident-protect" tabindex="-1">netapp-openshift-console-[trident,protect] <a class="header-anchor" href="#netapp-openshift-console-trident-protect" aria-label="Permalink to &quot;netapp-openshift-console-[trident,protect]&quot;">​</a></h1><p>The open-source projects netapp-openshift-console-[trident,protect] have been designed to improve the user experience connecting Red Hat OpenShift with the NetApp portfolio.</p><p>netapp-openshift-console-[trident,protect] deploys as a native Red Hat OpenShift console plugin enabling a graphical user interface to:</p><ul><li>Accelerate the deployment of Trident and Trident Protect.</li><li>Simplify the usage of Trident features like volumes, snapshots, etcs.</li><li>Simplify the usage of Protect features like Application Reference, Scheduling, Snapshots, Backups, Restore, etcs.</li><li>Provide application pattern deployment for fast prototyping up to production.</li><li>Enable dataset management for workload running in Red Hat OpenShift, OpenShift AI, and Developer Hub.</li></ul><h2 id="pre-requisites-and-deployment" tabindex="-1">Pre-requisites and Deployment <a class="header-anchor" href="#pre-requisites-and-deployment" aria-label="Permalink to &quot;Pre-requisites and Deployment&quot;">​</a></h2><p>These projects are currently in a pre-release phase and requires an Early Access Program agreement granting access to deploy the plugins on your Red Hat OpenShift cluster.<br> The netapp-openshift-console-[trident,protect] plugins are compatible with Red Hat OpenShift Container Platform <strong>4.14, 4.15, 4.16, and 4.17</strong>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The projects are provided <strong>AS-IS</strong> under the <a href="https://github.com/NetApp/netapp-openshift-console-%5Btrident,protect%5D?tab=Apache-2.0-1-ov-file#readme" target="_blank" rel="noreferrer">Apache 2.0 License</a> with community support only. For any questions, open a GitHub Issue.</p></div>',7)])])}const f=t(a,[["render",p]]);export{u as __pageData,f as default};
